// Runtime files are located the same way emscripten and wasm-bindgen output does
export async function test(readFile) {
  const data = await readFile(new URL("../assets/data.txt", import.meta.url), "utf8");
  if (data.trim() !== "OK") {
    return "FAILED: data";
  }
  const wasm = await readFile(new URL("sum.wasm", import.meta.url));
  const { instance } = await WebAssembly.instantiate(wasm);
  if (instance.exports.sum(1, 2) !== 3) {
    return "FAILED: sum";
  }
  return "OK";
}

// Left as-is: missing file, JS file and dynamic path
export const untouched = (name) => [
  new URL("./missing.bin", import.meta.url),
  new URL("./worker.mjs", import.meta.url),
  new URL(`./${name}.bin`, import.meta.url),
];
